    verifierKey: TAccountMetas[4];
    stakeVault: TAccountMetas[5];
    beneficiaryTokenAccount: TAccountMetas[6];
    beneficiary: TAccountMetas[7];
    treasuryTokenAccount: TAccountMetas[8];
    treasury: TAccountMetas[9];
